from __future__ import absolute_import
from selenium.webdriver.common.by import By
from .LoginPage import NomLoginPage
from .common_page import CommonPage
import time
import random
import re


class Incidents(CommonPage):
    """
    The class corresponding to 'Incidents' page on selenium_coam web, all operations under 'Incidents'
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver):
        if not self._instance_dict:
            self._instance_dict = {
                "Alarm View": AlarmViewPage(driver)
            }
        super(Incidents, self).__init__(driver, self._instance_dict)


class AlarmViewPage(NomLoginPage):
    MENU_ROUTE_LIST = ['alarm-view']
    ALL_FILTER_CONDITIONS = ['acknowledge_status', 'acknowledge_user', 'alarm_id', 'alarm_text',
                             'alarm_status', 'alarm_time', 'alarm_type', 'clear_user', 'integrated_id',
                             'last_update', 'probable_cause', 'specific_problem', 'system_distinguished_name',
                             'distinguished_name']
    _FILTER_FIRST_FIELD_XPATH = '//input[contains(@id, "first-input-first-field")]'
    _FILTER_CONDITION_INPUT_XPATH = '//input[contains(@id, "first-input-condition")]'
    _FILTER_CONDITION_SELECT_XPATH = '//div[@data-test="ccfk-list-item" and contains(text(), "Equals")]//..'
    _FILTER_QUERY_INPUT_XPATH = '//input[contains(@id, "first-input-query")]'
    _FILTER_QUERY_SELECT_XPATH = '//div[@data-test="ccfk-list-item" and text()="{}"]//..'
    _FILTER_CLOSE_XPATH = '//div[contains(@id, "chip-closeButton")]'
    _ACKNOWLEDGE_ALARM_XPATH = '//button[@aria-label="acknowledge alarm"]'
    _CANCEL_ALARM_XPATH = '//button[@aria-label="cancel alarm"]'
    _ALARM_ACK_ATTRIBUTE_XPATH = \
        '//div[contains(@row-id, "{}") and contains(@id, "actions-header")]/div[@col-id="ackUser"]'
    _ALARM_BODY_XPATH = '//div[@ref="eBodyViewport"]'
    _ALARM_VIEW_FRAME_XPATH = '//iframe[@name="alarm-view"]'
    _INCIDENTS_TOOLBAR_XPATH = '//div[@class="flex-toolbar-item" and text()="Incidents"]'
    _INCIDENTS_PAGE_XPATH = '//div[@data-key="alarm-view" and contains(@style, "position: fixed")]'
    _INCIDENTS_MENU_XPATH = '//li[@id="alarm-view"]'
    # _ALARM_FIRST_ROW_XPATH = '//div[@class="ag-pinned-right-cols-container"]/div[@row-index="0"]'
    _ALARM_FIRST_ROW_XPATH = '//div[@class="ag-center-cols-container"]/div[@row-index="0"]'
    _HISTORY_ALARM_XPATH = '//button[@id="historical-toggleBtn-button"]'
    _TRIGGER_WARNINGS_BUTTON = '//div[@id="warning-content"]'

    _COL_ID = {"severity": "severity",
               "alarm_time": "firstNotificationTime",
               "alarm_type": "alarmType",
               "specific_problem": "specificProblem",
               "alarm_text": "alarmText",
               "distinguished_name": "dn",
               "acknowledge_user": "ackUser",
               "additional_text": "additionalAlarmText1"
               }

    _ALARM_ROW_NUM = '//div[@row-index]/div[@col-id="severity"]'
    _COL_XPATH = '//div[@row-index="{}"]/div[@col-id="{}"]'
    _MORE_OPTIONS_ELEMENT = '//*[@id="csf-data-grid-3-header-more-menu-button-subMenuBtn-content"]'
    _MANAGE_COLUMNS_OPTION = '//div[text()="Manage Columns ..."]/..'
    # _MANAGE_COLUNMS_ITEM = '//label[text()="{}"]/../../../../../div[@class="own-checkbox"]'
    _MANAGE_COLUNMS_ITEM = '//div[contains(@id, "{}")]'
    _APPLY_BUTTON = '//span[text()="Apply"]/..'

    def get_alarms(self, **kwargs):
        # self._driver.switch_to_frame("alarm-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("alarm-view"))
        self.click_element_by_xpath(self._MORE_OPTIONS_ELEMENT)
        self.click_element_by_xpath(self._MANAGE_COLUMNS_OPTION)
        time.sleep(1)
        self.click_element_by_xpath('//div[@class="avatar-overlay"]')
        time.sleep(1)
        self.click_element_by_xpath('//*[text()="Alphabetic"]/..')
        time.sleep(1)
        self.click_element_by_xpath(self._MANAGE_COLUNMS_ITEM.format("Supplementary-Information"))
        time.sleep(2)
        self.click_element_by_xpath(self._APPLY_BUTTON)
        if kwargs:
            self._input_alarm_filter_context(**kwargs)
        time.sleep(5)
        alarm_list = []
        row_objects = self._driver.find_elements_by_xpath(self._ALARM_ROW_NUM)
        row_num = len(row_objects)
        for row_index in range(0, row_num):
            alarm_dict = {}
            for key in self._COL_ID:
                cid = self._COL_ID[key]
                xpath = self._COL_XPATH.format(row_index, cid)
                print(xpath)
                if len(self.get_attribute_by_xpath(xpath, "title")) > 0:
                    alarm_dict[key] = self.get_attribute_by_xpath(xpath, "title")
                else:
                    alarm_dict[key] = self.get_text_by_xpath(xpath)
            alarm_list.append(alarm_dict)
        self._driver.switch_to_default_content()
        return alarm_list

    def acknowledge_alarm(self, **kwargs):
        # self._driver.switch_to_frame("alarm-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("alarm-view"))
        if kwargs:
            self._input_alarm_filter_context(**kwargs)
        acknowledged_alarm_id = self._acknowledge_random_alarm()
        if acknowledged_alarm_id:
            return self._get_acknowledged_alarm_ackuser(acknowledged_alarm_id, **kwargs)
        self._driver.switch_to_default_content()

    def _input_alarm_filter_context(self, **kwargs):
        filter_condition = {}
        for key, value in kwargs.items():
            if key not in self.ALL_FILTER_CONDITIONS:
                raise Exception("Got an unexpected filter condition-{}, "
                                "the condition should be in {}".format(key, ', '.join(self.ALL_FILTER_CONDITIONS)))
            key = key.replace('_', ' ').title()
            if 'Id' in key:
                key = key.replace('Id', 'ID')
            if "Distinguished Name" in key:
                key = key.replace('Distinguished Name', 'Object identifier')
            filter_condition[key] = value

        self._clear_filter()
        for key, value in filter_condition.items():
            self.insert_text_to_enable_element(locator=(By.XPATH, self._FILTER_FIRST_FIELD_XPATH),
                                               text=key)
            self.insert_text_to_enable_element(locator=(By.XPATH, self._FILTER_CONDITION_INPUT_XPATH),
                                               text="=")
            self.wait_for_visibility(locator=(By.XPATH, self._FILTER_CONDITION_SELECT_XPATH))
            self.click_element_by_xpath(self._FILTER_CONDITION_SELECT_XPATH)
            self.insert_text_to_enable_element(locator=(By.XPATH, self._FILTER_QUERY_INPUT_XPATH),
                                               text=value)
            self.wait_for_visibility(locator=(By.XPATH, self._FILTER_QUERY_SELECT_XPATH.format(value)))
            self.click_element_by_xpath(self._FILTER_QUERY_SELECT_XPATH.format(value))

        self.click_element_by_xpath(self._INCIDENTS_TOOLBAR_XPATH)
        self.wait_for_visibility(locator=(By.XPATH, self._ALARM_BODY_XPATH))
        time.sleep(3)

    def _clear_filter(self):
        if self.element_exists((By.XPATH, self._FILTER_CLOSE_XPATH)):
            elements = self._driver.find_elements_by_xpath(self._FILTER_CLOSE_XPATH)
            for element in elements:
                element.click()

    def _acknowledge_random_alarm(self):
        # self.perform_element_hover_by_xpath(self._ALARM_FIRST_ROW_XPATH)
        self.wait_for_visibility(locator=(By.XPATH, self._ALARM_FIRST_ROW_XPATH))
        self.click_element_by_xpath(self._ALARM_FIRST_ROW_XPATH)
        elements = self._driver.find_elements_by_xpath(self._ACKNOWLEDGE_ALARM_XPATH)
        if elements:
            ele = random.choice(elements)
            parent_ele = ele.find_element_by_xpath('../../../../..')
            row_id_t = parent_ele.get_attribute('row-id')
            # acked_alarm_row_id = re.search('(.*)(unacked|acked|null)', row_id_t).group(1)
            ele.click()
            time.sleep(2)
            # return acked_alarm_row_id
            return row_id_t
        else:
            raise Exception("no alarm can be acknowledged")

    def _get_acknowledged_alarm_ackuser(self, alarm_row_id, **kwargs):
        self.refresh_page()
        self.wait_for_visibility(locator=(By.XPATH, self._INCIDENTS_MENU_XPATH))
        if not self.element_exists((By.XPATH, self._INCIDENTS_PAGE_XPATH), timeout=20):
            self.click_enabled_element((By.XPATH, self._INCIDENTS_MENU_XPATH))
        self.wait_for_visibility(locator=(By.XPATH, self._ALARM_VIEW_FRAME_XPATH))
        # self._driver.switch_to_frame("alarm-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("alarm-view"))
        if kwargs:
            self._input_alarm_filter_context(**kwargs)
        self.wait_for_visibility(locator=(By.XPATH, self._ALARM_ACK_ATTRIBUTE_XPATH.format(alarm_row_id)))
        endtime = 30 + time.time()
        while time.time() < endtime:
            acked_ele = self._driver.find_element_by_xpath(self._ALARM_ACK_ATTRIBUTE_XPATH.format(alarm_row_id))
            ack_user = acked_ele.get_attribute('textContent')
            if ack_user:
                return ack_user
            else:
                time.sleep(1)
        raise Exception("can not get the acknowledge user")

    def cancel_alarm(self, **kwargs):
        # self._driver.switch_to_frame("alarm-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("alarm-view"))
        if kwargs:
            self._input_alarm_filter_context(**kwargs)
        self._cancel_random_alarm()
        self._driver.switch_to_default_content()

    def _cancel_random_alarm(self):
        # self.perform_element_hover_by_xpath(self._ALARM_FIRST_ROW_XPATH)
        self.wait_for_visibility(locator=(By.XPATH, self._ALARM_FIRST_ROW_XPATH))
        self.click_element_by_xpath(self._ALARM_FIRST_ROW_XPATH)
        elements = self._driver.find_elements_by_xpath(self._CANCEL_ALARM_XPATH)
        if elements:
            ele = random.choice(elements)
            ele.click()
        else:
            raise Exception("no alarm can be canceled")

    def get_alarm_history(self, **kwargs):
        # self._driver.switch_to_frame("alarm-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("alarm-view"))
        if kwargs:
            self._input_alarm_filter_context(**kwargs)
        self.click_enabled_element((By.XPATH, self._HISTORY_ALARM_XPATH))
        self._driver.switch_to_default_content()

    def get_historical_alarms(self, **kwargs):
        # self._driver.switch_to_frame("alarm-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("alarm-view"))
        # if kwargs:
        #     self._input_alarm_filter_context(**kwargs)

        self.click_element_by_xpath(self._HISTORY_ALARM_XPATH)
        time.sleep(5)
        self.click_element_by_xpath(self._TRIGGER_WARNINGS_BUTTON)
        time.sleep(2)
        self.click_element_by_xpath(self._MORE_OPTIONS_ELEMENT)
        self.click_element_by_xpath(self._MANAGE_COLUMNS_OPTION)
        self.click_element_by_xpath('//div[@class="avatar-overlay"]')
        time.sleep(1)
        self.click_element_by_xpath('//*[text()="Alphabetic"]/..')
        time.sleep(1)
        self.click_element_by_xpath(self._MANAGE_COLUNMS_ITEM.format("Supplementary-Information"))
        time.sleep(2)
        self.click_element_by_xpath(self._APPLY_BUTTON)
        if kwargs:
            self._input_alarm_filter_context(**kwargs)
        time.sleep(5)
        alarm_list = []
        row_objects = self._driver.find_elements_by_xpath(self._ALARM_ROW_NUM)
        row_num = len(row_objects)
        for row_index in range(0, row_num):
            alarm_dict = {}
            for key in self._COL_ID:
                cid = self._COL_ID[key]
                xpath = self._COL_XPATH.format(row_index, cid)
                if len(self.get_attribute_by_xpath(xpath, "title")) > 0:
                    alarm_dict[key] = self.get_attribute_by_xpath(xpath, "title")
                else:
                    alarm_dict[key] = self.get_text_by_xpath(xpath)
            alarm_list.append(alarm_dict)
        self._driver.switch_to_default_content()
        return alarm_list
